{
  "claims": [
    {
      "kind": "quantitative",
      "text": "Walmart's revenue grew from {{m:revenue:FY-2}} in {{p:FY-2}} to {{m:revenue:FY0}} in {{p:FY0}}, reaching {{m:revenue:LTM}} in {{p:LTM}}.",
      "citations": []
    },
    {
      "kind": "quantitative",
      "text": "The company generated EBITDA of {{m:ebitda:FY0}} in {{p:FY0}} and {{m:ebitda:LTM}} in {{p:LTM}}, reflecting its substantial scale and profitability.",
      "citations": []
    },
    {
      "kind": "qualitative",
      "text": "Walmart operates three business segments—Walmart U.S., Walmart International, and Sam's Club U.S.—across multiple countries and retail formats.",
      "citations": [
        {
          "chunk_id": "WMT-000010416926000055-0148",
          "quote": "the financial results of each of the three segments of our business"
        },
        {
          "chunk_id": "WMT-000010416926000055-0031",
          "quote": "strategically located in Africa, Canada, Central America, Chile, China, India and Mexico"
        }
      ]
    },
    {
      "kind": "qualitative",
      "text": "Walmart's business is seasonal, with the highest sales volume for each segment occurring in the fiscal fourth quarter, introducing some variability in quarterly cash flows.",
      "citations": [
        {
          "chunk_id": "WMT-000010416926000055-0029",
          "quote": "Historically, our highest sales volume for each segment has occurred in the fourth quarter of our fiscal year"
        }
      ]
    },
    {
      "kind": "qualitative",
      "text": "Walmart faces intense competition from brick-and-mortar, eCommerce, and omnichannel retailers, but its omnichannel model and low-price positioning help sustain customer traffic.",
      "citations": [
        {
          "chunk_id": "WMT-000010416926000055-0027",
          "quote": "Each of these landscapes is highly competitive and rapidly evolving"
        },
        {
          "chunk_id": "WMT-000010416926000055-0030",
          "quote": "which in turn enables us to provide low prices to our customers"
        }
      ]
    }
  ]
}

{
  "claims": [
    {
      "kind": "quantitative",
      "text": "For {{p:LTM}}, cash and cash equivalents were {{m:cash:LTM}} and cash from operations was {{m:cfo:LTM}}, while short-term debt was {{m:short_term_debt:LTM}}, capital expenditure was {{m:capex:LTM}}, and dividends paid were {{m:dividends:LTM}}; liquidity coverage was {{m:liquidity_coverage:LTM}}.",
      "citations": []
    },
    {
      "kind": "quantitative",
      "text": "For {{p:FY0}}, liquidity coverage was {{m:liquidity_coverage:FY0}}.",
      "citations": []
    },
    {
      "kind": "qualitative",
      "text": "At July 31, 2026, Walmart had committed lines of credit in the U.S. of $15.0 billion, all undrawn.",
      "citations": [
        {
          "chunk_id": "WMT-000010416926000154-0069",
          "quote": "In total, we had committed lines of credit in the U.S. of $15.0 billion at July 31, 2026, all undrawn."
        }
      ]
    },
    {
      "kind": "qualitative",
      "text": "In April 2026, the Company renewed and extended its existing 364-day revolving credit facility of $10.0 billion as well as its five-year credit facility of $5.0 billion.",
      "citations": [
        {
          "chunk_id": "WMT-000010416926000154-0069",
          "quote": "In April 2026, the Company renewed and extended its existing 364-day revolving credit facility of $10.0 billion as well as its five-year credit facility of $5.0 billion."
        }
      ]
    }
  ]
}

{
  "claims": [
    {
      "kind": "qualitative",
      "text": "Adverse macroeconomic conditions, including recession, tariffs, import or export restrictions, or other taxes, could reduce consumer demand and lower net sales and operating income, weakening internal cash flow available for debt service.",
      "citations": [
        {
          "chunk_id": "WMT-000010416926000055-0056",
          "quote": "overall economic slowdown or recession and other economic factors in the U.S., or in any of the other markets in which we operate, could adversely affect consumer demand"
        }
      ]
    },
    {
      "kind": "qualitative",
      "text": "Walmart International's operations face political, legal, tax, foreign exchange, and trade restrictions that could reduce or constrain the cash generated in those markets and its contribution to consolidated debt repayment.",
      "citations": [
        {
          "chunk_id": "WMT-000010416926000055-0098",
          "quote": "Our future operating results in these countries could be negatively affected by a variety of factors"
        }
      ]
    },
    {
      "kind": "qualitative",
      "text": "Widespread health crises affecting humans or the food supply could disrupt supply chain operations, raise costs, and reduce demand, adversely affecting financial performance and cash flow.",
      "citations": [
        {
          "chunk_id": "WMT-000010416926000055-0059",
          "quote": "could impact our business operations, demand for our products and services, in-stock positions, costs of doing business, access to inventory, supply chain operations"
        }
      ]
    },
    {
      "kind": "qualitative",
      "text": "Changes in pharmacy laws, regulations, or third-party payer practices and failures to comply with financial-services laws could result in lower reimbursement, fines, or penalties, reducing profitability and cash available for debt repayment.",
      "citations": [
        {
          "chunk_id": "WMT-000010416926000055-0090",
          "quote": "changes in laws or regulations or the practices of third-party payers and PBMs"
        },
        {
          "chunk_id": "WMT-000010416926000055-0111",
          "quote": "Failure to comply with these laws and regulations could result in fines, sanctions, penalties and harm to our reputation."
        }
      ]
    },
    {
      "kind": "qualitative",
      "text": "Failure to execute the omnichannel strategy or manage eCommerce and technology investment costs could materially weaken market position, net sales, and financial performance, with a corresponding effect on cash flow.",
      "citations": [
        {
          "chunk_id": "WMT-000010416926000055-0044",
          "quote": "Failure to successfully execute our omnichannel strategy and the cost of our investments in eCommerce and technology may materially adversely affect our market position, net sales and financial performance."
        }
      ]
    }
  ]
}
